"% Noisy sampled-data identification of the short-period mode.
dt = 0.02;

% Validate the supplied sampled-response dimensions.
if size(X,2) ~= 4 || numel(u) ~= size(X,1)
    error('Expected X to be N-by-4 and u to be N-by-1 with the same N.');
end

% x[k+1] = Ad*x[k] + Bd*delta_e[k]
Phi = [X(1:end-1,:), u(1:end-1)];
Theta = Phi \ X(2:end,:);

Ad = Theta(1:4,:).';
Bd = Theta(5,:).';

% Convert the discrete eigenvalues to continuous-time poles.
lambda = eig(Ad);
sPoles = log(lambda) / dt;

% The short-period mode is the stable conjugate pair farthest from the
% origin in the continuous-time plane.
[~, idx] = sort(abs(sPoles), 'descend');
p = sPoles(idx(1));
[~, idxPair] = min(abs(sPoles - conj(p)));
pPair = sPoles(idxPair);

% Average the two members of the selected conjugate pair.
p = 0.5 * (p + pPair);

omega_sp_id = abs(p);
zeta_sp_id = -real(p) / omega_sp_id;

result = struct( ...
    'omega_sp_id', omega_sp_id, ...
    'zeta_sp_id', zeta_sp_id);

fid = fopen('result.json', 'w');
if fid == -1
    error('Unable to open result.json for writing.');
end
fwrite(fid, jsonencode(result), 'char');
fwrite(fid, sprintf('\n'), 'char');
fclose(fid);"

